function distributeRewards(uint256 rewardPerHolder) public {
    require(msg.sender == owner, "Only owner can distribute rewards");
    uint256 totalReward = 0;
    for (uint256 i = 0; i < holders.length; i++) {
        balances[holders[i]] += rewardPerHolder;
        totalReward += rewardPerHolder;
    }
    totalSupply += totalReward;
}

mapping(address => bool) private _isHolder;
function mint(address to, uint256 amount) public {
    require(msg.sender == owner, "Only owner");
    totalSupply += amount;
    balances[to] += amount;
    if (!_isHolder[to]) {
        holders.push(to);
        _isHolder[to] = true;
    }
}

function batchTransfer(address[] memory to, uint256[] memory amounts) public {
    require(to.length == amounts.length, "Mismatched arrays");
    for (uint256 i = 0; i < to.length; i++) {
        require(balances[msg.sender] >= amounts[i], "Insufficient balance");
        balances[msg.sender] -= amounts[i];
        balances[to[i]] += amounts[i];
    }
}
